failed = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        failed.append(what)


CASES = [({"kind": "fx", "key": "sx"}, "Effect"), ({"kind": "check", "key": "o1"}, "Effect"),
         ({"kind": "next"}, "Effect"), ({"kind": "pad_effect", "name": ""}, "Effect"),
         ({"kind": "vj_fader"}, "Mix"), ({"kind": "vj_cut"}, "Mix"), ({"kind": "vj_sel_b"}, "Mix"),
         ({"kind": "vj_sel_next"}, "Mix"), ({"kind": "mixer"}, "Mix"), ({"kind": "vj_air"}, "Mix"),
         ({"kind": "vj_knob", "deck": 0, "key": "hue"}, "Deck A"), ({"kind": "vj_look", "deck": 1}, "Deck B"),
         ({"kind": "pad_clip", "deck": 2}, "Deck C"), ({"kind": "pad_look", "deck": vj.SEL, "look": ""}, "Selected deck"),
         ({"kind": "vj_fx", "deck": vj.SEL, "key": "sx"}, "Selected deck"),
         ({"kind": "vj_clip_b"}, "Deck B"), ({"kind": "vj_pause_s"}, "Selected deck"), ({"kind": "vj_shuffle_a"}, "Deck A"),
         ({"kind": "vj_c_flash"}, "Deck C"), ({"kind": "mod", "id": 3, "key": "rate"}, "Modulators"),
         ({"kind": "mod_on", "id": 3}, "Modulators"), ({"kind": "something new"}, "Other")]
