rows = P.grouped(app, items)
check(rows == [P.header("Effect"), "Speed", P.header("Mix"), "VJ: the crossfader", P.header("Deck A"), "VJ A: hue",
               P.header("Modulators"), "LFO 1: rate"], f"the groups in order, empty ones left out ({rows})")
